"""Generate LLM instruction files for the migration agent."""

from __future__ import annotations

from dataclasses import asdict
from pathlib import Path

from quickhatch.config import UserProfile


def generate_instructions(profile: UserProfile) -> str:
    """Generate a comprehensive instruction document for the AI agent."""
    prefs = profile.preferences
    hw = profile.hardware
    ai = profile.ai_config

    sections = []

    # Header
    sections.append(
        "# QuickHatch Migration Instructions\n"
        "# Generated by QuickHatch - Windows to Linux Migration Wizard\n"
        "# This file contains instructions for the AI agent to complete the migration.\n"
    )

    # Migration overview
    sections.append(
        "## Migration Overview\n\n"
        f"- **Migration type:** {prefs.migration_type}\n"
        f"- **Target distro:** {profile.recommended_distro or 'Not selected'}\n"
        f"- **Desktop environment:** {profile.recommended_desktop or 'Default'}\n"
        f"- **AI provider:** {ai.provider}\n"
    )

    # Hardware summary
    sections.append("## Hardware Summary\n")
    sections.append(f"- **CPU:** {hw.cpu} ({hw.cpu_cores} cores)\n")
    sections.append(f"- **RAM:** {hw.ram_gb} GB\n")
    for gpu in hw.gpus:
        vram = f" ({gpu.vram_mb} MB VRAM)" if gpu.vram_mb else ""
        sections.append(f"- **GPU:** {gpu.name}{vram} [{gpu.vendor}]\n")
    if hw.wifi_adapters:
        sections.append(f"- **WiFi:** {', '.join(hw.wifi_adapters)}\n")
    sections.append(f"- **Bluetooth:** {'Yes' if hw.bluetooth else 'No'}\n")
    sections.append(f"- **EFI boot:** {'Yes' if hw.efi else 'No (Legacy BIOS)'}\n")
    sections.append("")

    # Driver installation instructions
    sections.append("## Driver Setup Instructions\n")
    for gpu in hw.gpus:
        if gpu.vendor == "nvidia":
            sections.append(
                "### NVIDIA GPU Driver\n"
                "Install proprietary NVIDIA drivers for best performance:\n"
                "```bash\n"
                "# Ubuntu/Pop!_OS/Mint:\n"
                "sudo ubuntu-drivers autoinstall\n"
                "# Fedora:\n"
                "sudo dnf install akmod-nvidia\n"
                "# Arch/Manjaro:\n"
                "sudo pacman -S nvidia nvidia-utils\n"
                "```\n"
            )
        elif gpu.vendor == "amd":
            sections.append(
                "### AMD GPU\n"
                "AMD GPUs use the open-source AMDGPU driver built into the kernel.\n"
                "No additional installation needed. For Vulkan support:\n"
                "```bash\n"
                "# Ubuntu: sudo apt install mesa-vulkan-drivers\n"
                "# Fedora: sudo dnf install vulkan-loader mesa-vulkan-drivers\n"
                "```\n"
            )

    if hw.wifi_adapters:
        sections.append(
            "### WiFi\n"
            "Ensure firmware is installed:\n"
            "```bash\n"
            "# Ubuntu/Debian: sudo apt install linux-firmware\n"
            "# Fedora: sudo dnf install linux-firmware\n"
            "```\n"
            "If WiFi doesn't work, identify the chipset with `lspci | grep -i net` "
            "and search for the specific driver.\n"
        )

    if hw.bluetooth:
        sections.append(
            "### Bluetooth\n"
            "```bash\n"
            "sudo systemctl enable --now bluetooth\n"
            "```\n"
        )

    # Desktop environment setup
    sections.append("## Desktop Environment Setup\n")

    de_instructions = {
        "windows_like": (
            "User wants a Windows-like desktop experience.\n"
            "- Install **KDE Plasma** or **Cinnamon** desktop\n"
            "- Place taskbar at the bottom\n"
            "- Configure a start/application menu\n"
            "- Set up familiar keyboard shortcuts (Win key for menu, etc.)\n"
        ),
        "macos_like": (
            "User wants a macOS-like desktop experience.\n"
            "- Install **GNOME** with Dash-to-Dock extension, or **Pantheon**\n"
            "- Add a dock at the bottom with frequently used apps\n"
            "- Configure top bar with system tray\n"
            "- Enable hot corners if available\n"
        ),
        "minimal": (
            "User wants a minimal, distraction-free desktop.\n"
            "- Install **XFCE** or **LXQt** for lightweight minimal setup\n"
            "- Keep the desktop clean with minimal panels\n"
            "- Focus on keyboard shortcuts for efficiency\n"
        ),
        "tiling": (
            "User wants a tiling window manager.\n"
            "- Install **Hyprland** (Wayland) or **i3** (X11)\n"
            "- Configure with waybar/polybar for status bar\n"
            "- Set up workspace keybindings\n"
            "- Configure rofi/wofi as application launcher\n"
        ),
    }
    sections.append(
        de_instructions.get(prefs.desktop_look, "Configure desktop environment per user preference.\n")
    )

    # Theming
    sections.append("## Theming Preferences\n")
    icon_map = {
        "flat": "Install Papirus icon theme: `sudo apt install papirus-icon-theme` (or equivalent)",
        "rounded": "Install Tela icon theme from GitHub or package manager",
        "classic": "Use the distro's default icon theme",
        "colorful": "Install Numix or Candy icon theme",
        "default": "Use the distro's default icon theme",
    }
    sections.append(f"- **Icons:** {icon_map.get(prefs.icon_style, 'Default')}\n")

    wallpaper_map = {
        "nature": "Set a nature/landscape wallpaper. Search for 4K nature wallpapers.",
        "abstract": "Set an abstract/geometric wallpaper.",
        "dark": "Set a dark/moody wallpaper to complement dark theme.",
        "minimal": "Set a minimal/clean wallpaper with muted colors.",
        "custom": "User will set their own wallpaper.",
    }
    sections.append(f"- **Wallpaper:** {wallpaper_map.get(prefs.wallpaper_style, 'Default')}\n")

    theme = profile.windows_settings.get("theme", "unknown")
    if theme == "dark":
        sections.append("- **System theme:** Dark mode (user was using dark mode on Windows)\n")
    elif theme == "light":
        sections.append("- **System theme:** Light mode\n")
    sections.append("")

    # Applications to install
    sections.append("## Applications to Install\n")
    sections.append("Install these applications to match the user's Windows setup:\n\n")

    native_apps = [a for a in profile.apps if a.compatibility == "native"]
    alt_apps = [a for a in profile.apps if a.compatibility == "alternative"]
    wine_apps = [a for a in profile.apps if a.compatibility == "wine"]

    if native_apps:
        sections.append("### Native Linux Apps\n")
        for app in native_apps:
            alt = app.linux_alternative or app.name
            sections.append(f"- **{app.name}** -> {alt}\n")
        sections.append("")

    if alt_apps:
        sections.append("### Linux Alternatives\n")
        for app in alt_apps:
            sections.append(
                f"- **{app.name}** -> {app.linux_alternative}"
                + (f" ({app.notes})" if app.notes else "")
                + "\n"
            )
        sections.append("")

    if wine_apps:
        sections.append("### Wine/Proton Apps\n")
        sections.append("These may need Wine or Proton to run:\n")
        for app in wine_apps:
            sections.append(
                f"- **{app.name}** -> {app.linux_alternative or 'Try with Wine'}"
                + (f" ({app.notes})" if app.notes else "")
                + "\n"
            )
        sections.append("")

    # File transfer notes
    if profile.files_summary:
        sections.append("## File Transfer Notes\n")
        sections.append(
            f"- Total files scanned: {profile.files_summary.get('total_files', 0)}\n"
            f"- Total size: {profile.files_summary.get('total_size_mb', 0)} MB\n"
        )
        browsers = profile.files_summary.get("browser_profiles", {})
        if browsers:
            sections.append("\n### Browser Data to Migrate\n")
            for browser in browsers:
                sections.append(f"- {browser.title()}: Export bookmarks and sync data\n")
        sections.append("")

    # SSH setup
    if profile.ssh_public_key_path:
        sections.append(
            "## SSH Access\n\n"
            f"Public key file: `{profile.ssh_public_key_path}`\n\n"
            "To enable agent access on the new Linux machine:\n"
            "```bash\n"
            "mkdir -p ~/.ssh && chmod 700 ~/.ssh\n"
            "# Copy the public key content to authorized_keys:\n"
            "echo '<PUBLIC_KEY_CONTENT>' >> ~/.ssh/authorized_keys\n"
            "chmod 600 ~/.ssh/authorized_keys\n"
            "sudo systemctl enable --now sshd\n"
            "```\n"
        )

    # AI agent configuration
    sections.append("## AI Agent Configuration\n")
    if ai.provider == "claude_code":
        sections.append(
            "Install and run Claude Code:\n"
            "```bash\n"
            "# Install Node.js if not present\n"
            "curl -fsSL https://deb.nodesource.com/setup_lts.x | sudo -E bash -\n"
            "sudo apt install -y nodejs\n"
            "# Install Claude Code\n"
            "npm install -g @anthropic-ai/claude-code\n"
            "# Run with this instruction file\n"
            "claude\n"
            "```\n"
        )
    elif ai.provider == "codex":
        sections.append(
            "Install and run Codex:\n"
            "```bash\n"
            "npm install -g @openai/codex\n"
            "codex\n"
            "```\n"
        )
    elif ai.provider == "local_ollama":
        sections.append(
            "Install and run Ollama:\n"
            "```bash\n"
            "curl -fsSL https://ollama.ai/install.sh | sh\n"
            f"ollama pull {ai.model_name or 'llama3'}\n"
            f"ollama run {ai.model_name or 'llama3'}\n"
            "```\n"
        )
    elif ai.provider == "local_lmstudio":
        sections.append(
            "Install LM Studio from: https://lmstudio.ai\n"
            f"Load model: {ai.model_name or 'your chosen model'}\n"
        )
    elif ai.provider == "api":
        sections.append(
            f"API endpoint: {ai.endpoint}\n"
            f"Model: {ai.model_name}\n"
            "API key is stored in the migration bundle.\n"
        )

    # Additional user notes
    if prefs.additional_notes:
        sections.append(
            f"\n## Additional User Notes\n\n{prefs.additional_notes}\n"
        )

    # Post-install checklist
    sections.append(
        "\n## Post-Installation Checklist\n\n"
        "After installing Linux, the AI agent should:\n"
        "1. Update the system: `sudo apt update && sudo apt upgrade` (or equivalent)\n"
        "2. Install GPU drivers (see above)\n"
        "3. Install and configure the desktop environment\n"
        "4. Apply theming (icons, wallpaper, dark/light mode)\n"
        "5. Install all applications listed above\n"
        "6. Import browser bookmarks\n"
        "7. Set up development tools if needed\n"
        "8. Configure SSH for remote access\n"
        "9. Transfer user files from Windows\n"
        "10. Verify hardware (WiFi, Bluetooth, audio, display)\n"
    )

    return "\n".join(sections)


def save_instructions(profile: UserProfile, output_dir: Path) -> Path:
    """Generate and save instruction files."""
    output_dir.mkdir(parents=True, exist_ok=True)

    # Main instruction file
    instructions = generate_instructions(profile)
    inst_path = output_dir / "MIGRATION_INSTRUCTIONS.md"
    inst_path.write_text(instructions)

    return inst_path
